const keys={},kbKeys={},padKeys={},pressed={};
const p2Keys={},p2KbKeys={},p2PadKeys={},p2Pressed={};
const P2_KEYMAP={
 ArrowLeft:'KeyA',ArrowRight:'KeyD',ArrowUp:'KeyW',ArrowDown:'KeyS',
 Numpad1:'KeyJ',Numpad2:'KeyK',Numpad3:'KeyL',Numpad4:'KeyU',Numpad5:'KeyI',Numpad0:'ShiftLeft'
};
const SYSTEM_DEFAULT={
 controls:'CLASSIC',
 shake:true,
 flashes:true,
 reducedMotion:false,
 highContrast:false,
 particles:'NORMAL',
 deadzone:.45,
 vibration:true
};
let SYSTEM={...SYSTEM_DEFAULT};
try{let s=JSON.parse(localStorage.getItem('nightbloom_system')||'null');if(s)SYSTEM={...SYSTEM,...s}}catch(e){}
const CONTROL_PRESETS={
 CLASSIC:{
  ArrowLeft:'ArrowLeft',ArrowRight:'ArrowRight',ArrowUp:'ArrowUp',ArrowDown:'ArrowDown',
  KeyA:'KeyA',KeyD:'KeyD',KeyW:'KeyW',KeyS:'KeyS',KeyJ:'KeyJ',KeyK:'KeyK',KeyL:'KeyL',KeyU:'KeyU',KeyI:'KeyI',
  ShiftLeft:'ShiftLeft',ShiftRight:'ShiftRight'
 },
 ARCADE:{
  ArrowLeft:'KeyA',ArrowRight:'KeyD',ArrowUp:'KeyW',ArrowDown:'KeyS',
  KeyZ:'KeyJ',KeyX:'KeyK',KeyC:'KeyL',KeyV:'KeyU',KeyB:'KeyI',KeyN:'ShiftLeft'
 }
};
function saveSystem(){try{localStorage.setItem('nightbloom_system',JSON.stringify(SYSTEM))}catch(e){}}
function mapInputCode(code){return CONTROL_PRESETS[SYSTEM.controls]?.[code]||code}
addEventListener('keydown',e=>{
 if(e.target.closest?.('#help'))return;
 if(gameMode==='local'&&gameState==='fight'&&P2_KEYMAP[e.code]){
   let code=P2_KEYMAP[e.code];
   if(!p2Keys[code])p2Pressed[code]=1;
   p2KbKeys[code]=1;p2Keys[code]=1;e.preventDefault();return;
 }
 let code=(gameMode==='local'&&gameState==='fight')?(CONTROL_PRESETS.CLASSIC[e.code]||e.code):mapInputCode(e.code);
 if(!keys[code])pressed[code]=1;
 kbKeys[code]=1;keys[code]=1;
 if(["ArrowUp","ArrowDown","ArrowLeft","ArrowRight","Space"].includes(e.code))e.preventDefault()
});
addEventListener('keyup',e=>{
 if(gameMode==='local'&&gameState==='fight'&&P2_KEYMAP[e.code]){
   let code=P2_KEYMAP[e.code];p2KbKeys[code]=0;p2Keys[code]=!!p2PadKeys[code];e.preventDefault();return;
 }
 let code=(gameMode==='local'&&gameState==='fight')?(CONTROL_PRESETS.CLASSIC[e.code]||e.code):mapInputCode(e.code);
 kbKeys[code]=0;keys[code]=!!padKeys[code];
});

function pauseForFocusLoss(){
 if(gameState==='fight'&&!paused){
   paused=true;focusPaused=true;clearInputs();announcement='AUTO PAUSED';announceT=45;
   if(audioCtx&&audioMusic){musicDuck=.25;applyAudioLevels()}
 }
}
addEventListener('blur',pauseForFocusLoss);
document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseForFocusLoss()});


// ---------- AUDIO ENGINE ----------
let audioCtx=null,audioMaster=null,audioMusic=null,audioSfx=null,audioUnlocked=false;
let musicNext=0,musicStep=0,musicKey='',lastMusicState='',musicDuck=1;
const AUDIO_DEFAULT={master:.72,music:.34,sfx:.74,mute:false};
let AUDIO={...AUDIO_DEFAULT};
try{let saved=JSON.parse(localStorage.getItem('nightbloom_audio')||'null');if(saved)AUDIO={...AUDIO,...saved}}catch(e){}
const OPTIONS=['MASTER VOLUME','MUSIC VOLUME','SFX VOLUME','MUTE','CONTROL PRESET','GAMEPAD DEADZONE','VIBRATION','SCREEN SHAKE','SCREEN FLASHES','REDUCED MOTION','HIGH CONTRAST HUD','PARTICLES','RESET PROGRESS'];
const STAGE_MUSIC={
 MENU:{root:110,bpm:72,wave:'triangle',pattern:[0,3,7,10,7,3,0,-2,0,5,8,7,3,0,-5,-2]},
 'CRIMSON CATHEDRAL':{root:110,bpm:126,wave:'sawtooth',pattern:[0,3,7,10,7,3,0,-2,0,3,8,10,8,3,0,-5]},
 'MOONLIT SHRINE':{root:130.81,bpm:104,wave:'triangle',pattern:[0,2,5,7,9,7,5,2,0,5,9,12,9,7,5,2]},
 'FORSAKEN HARBOR':{root:98,bpm:112,wave:'square',pattern:[0,3,5,8,5,3,-2,0,0,5,7,8,7,3,0,-4]},
 'CURSED LIBRARY':{root:123.47,bpm:96,wave:'triangle',pattern:[0,1,6,5,3,1,-1,0,0,6,8,7,3,1,-2,0]},
 'BONEFIELD':{root:82.41,bpm:118,wave:'sawtooth',pattern:[0,3,6,7,6,3,0,-5,0,6,7,10,7,3,0,-5]},
 'THE NEXT DAWN':{root:146.83,bpm:110,wave:'triangle',pattern:[0,4,7,9,7,4,2,0,0,4,7,12,11,7,4,2]}
};
const CHAR_AUDIO={
 VAMPIRA:{root:196,wave:'sawtooth'},
 NEKOMATA:{root:246.94,wave:'triangle'},
 BANSHEE:{root:329.63,wave:'sine'},
 MEDUSA:{root:174.61,wave:'square'},
 JIANGSHI:{root:293.66,wave:'square'},
 YUREI:{root:220,wave:'sine'},
 DULLAHAN:{root:146.83,wave:'sawtooth'},
 WEREWOLF:{root:130.81,wave:'sawtooth'},
 MUMMY:{root:164.81,wave:'square'},
 WITCH:{root:277.18,wave:'triangle'}
};
function saveAudio(){try{localStorage.setItem('nightbloom_audio',JSON.stringify(AUDIO))}catch(e){}}
function unlockAudio(){
 if(!audioCtx){
   const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;
   audioCtx=new AC();
   audioMaster=audioCtx.createGain();audioMusic=audioCtx.createGain();audioSfx=audioCtx.createGain();
   audioMusic.connect(audioMaster);audioSfx.connect(audioMaster);audioMaster.connect(audioCtx.destination);
 }
 if(audioCtx.state==='suspended')audioCtx.resume();
 audioUnlocked=true;applyAudioLevels(true);
 if(!musicNext)musicNext=audioCtx.currentTime+.05;
}
addEventListener('keydown',unlockAudio,{passive:true});
addEventListener('pointerdown',unlockAudio,{passive:true});
function applyAudioLevels(immediate=false){
 if(!audioCtx||!audioMaster)return;
 let t=audioCtx.currentTime,master=AUDIO.mute?0:AUDIO.master;
 let set=(param,val)=>immediate?param.setValueAtTime(val,t):param.setTargetAtTime(val,t,.025);
 set(audioMaster.gain,master);set(audioMusic.gain,AUDIO.music*musicDuck);set(audioSfx.gain,AUDIO.sfx);
}
function hz(root,semi){return root*Math.pow(2,semi/12)}
function tone(freq,dur=.08,wave='sine',vol=.18,delay=0,pan=0,bus='sfx'){
 if(!audioUnlocked||!audioCtx)return;
 let t=audioCtx.currentTime+delay,o=audioCtx.createOscillator(),g=audioCtx.createGain();
 o.type=wave;o.frequency.setValueAtTime(Math.max(25,freq),t);
 g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(.0001,vol),t+.008);
 g.gain.exponentialRampToValueAtTime(.0001,t+dur);
 if(audioCtx.createStereoPanner){let p=audioCtx.createStereoPanner();p.pan.setValueAtTime(clamp(pan,-1,1),t);o.connect(g);g.connect(p);p.connect(bus==='music'?audioMusic:audioSfx)}
 else{o.connect(g);g.connect(bus==='music'?audioMusic:audioSfx)}
 o.start(t);o.stop(t+dur+.025);
}
function sweep(from,to,dur=.12,wave='sawtooth',vol=.2,delay=0,pan=0){
 if(!audioUnlocked||!audioCtx)return;
 let t=audioCtx.currentTime+delay,o=audioCtx.createOscillator(),g=audioCtx.createGain();
 o.type=wave;o.frequency.setValueAtTime(from,t);o.frequency.exponentialRampToValueAtTime(Math.max(25,to),t+dur);
 g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+.006);g.gain.exponentialRampToValueAtTime(.0001,t+dur);
 if(audioCtx.createStereoPanner){let p=audioCtx.createStereoPanner();p.pan.value=pan;o.connect(g);g.connect(p);p.connect(audioSfx)}else{o.connect(g);g.connect(audioSfx)}
 o.start(t);o.stop(t+dur+.03);
}
function noiseBurst(dur=.06,vol=.14,pan=0){
 if(!audioUnlocked||!audioCtx)return;
 let len=Math.max(1,Math.floor(audioCtx.sampleRate*dur)),buf=audioCtx.createBuffer(1,len,audioCtx.sampleRate),arr=buf.getChannelData(0);
 for(let i=0;i<len;i++)arr[i]=(Math.random()*2-1)*(1-i/len);
 let s=audioCtx.createBufferSource(),g=audioCtx.createGain();s.buffer=buf;g.gain.value=vol;
 if(audioCtx.createStereoPanner){let p=audioCtx.createStereoPanner();p.pan.value=pan;s.connect(g);g.connect(p);p.connect(audioSfx)}else{s.connect(g);g.connect(audioSfx)}
 s.start();
}
function fighterPan(name){
 if(typeof p1==='undefined'||!p1)return 0;
 let f=p1.name===name?p1:p2.name===name?p2:null;
 return f?clamp((f.x-W/2)/(W/2),-0.8,.8):0;
}
function charCue(name,kind='special'){
 let c=CHAR_AUDIO[name]||CHAR_AUDIO.VAMPIRA,pan=fighterPan(name);
 if(kind==='super'){
   tone(c.root,.20,c.wave,.24,0,pan);tone(c.root*1.5,.23,'triangle',.19,.07,pan);tone(c.root*2,.28,'sine',.15,.14,pan);
 }else if(kind==='special'){
   sweep(c.root*1.4,c.root*2.3,.13,c.wave,.16,0,pan);
 }
}
function audioEvent(type,data={}){
 if(!audioUnlocked)return;
 let pan=data.attacker?fighterPan(data.attacker):data.fighter?fighterPan(data.fighter):0;
 if(type==='attack'){
   if(data.move==='light'||data.move==='lowlight'||data.move==='airlight')sweep(310,190,.045,'triangle',.08,0,pan);
   else if(data.move==='heavy'||data.move==='lowheavy'||data.move==='airheavy')sweep(240,95,.075,'sawtooth',.13,0,pan);
   else if(data.move==='specialA'||data.move==='specialB')charCue(data.fighter,'special');
   else if(data.move==='throw')sweep(180,95,.09,'square',.10,0,pan);
 }else if(type==='hit'){
   noiseBurst(.055,.12,pan);tone(85,.07,'square',.13,0,pan);
 }else if(type==='block'){
   tone(740,.055,'square',.12,0,pan);tone(510,.07,'triangle',.08,.025,pan);
 }else if(type==='super_start'){
   duckMusic(.24,.14);charCue(data.fighter,'super');
 }else if(type==='throw_tech'||type==='ground_tech'||type==='air_tech'){
   tone(620,.06,'triangle',.11,0,pan);tone(930,.09,'sine',.09,.04,pan);
 }else if(type==='round_start'){
   tone(220,.08,'square',.08);tone(330,.08,'square',.08,.09);tone(440,.13,'square',.10,.18);
 }else if(type==='ko'){
   duckMusic(.16,.5);sweep(160,42,.42,'sawtooth',.24);noiseBurst(.16,.18);
   tone(55,.38,'square',.16,.12);
 }else if(type==='match_end'){
   duckMusic(.22,.5);[0,4,7,12].forEach((s,i)=>tone(hz(220,s),.22,'triangle',.12,i*.09));
 }else if(type==='cancel'){
   tone(520,.035,'sine',.055,0,pan);
 }
}
function duckMusic(level=.25,seconds=.22){
 if(!audioCtx||!audioMusic)return;
 let t=audioCtx.currentTime;
 audioMusic.gain.cancelScheduledValues(t);
 audioMusic.gain.setTargetAtTime(AUDIO.music*level,t,.018);
 audioMusic.gain.setTargetAtTime(AUDIO.music,t+seconds,.07);
}
function musicTarget(){
 if(gameState==='fight')return selectedStage||'MENU';
 if(gameState==='storyScene'||gameState==='routeComplete')return 'CURSED LIBRARY';
 return 'MENU';
}
function musicTick(){
 if(!audioUnlocked||!audioCtx||AUDIO.mute)return;
 let key=musicTarget(),cfg=STAGE_MUSIC[key]||STAGE_MUSIC.MENU;
 if(key!==musicKey){musicKey=key;musicStep=0;musicNext=audioCtx.currentTime+.04}
 let now=audioCtx.currentTime,stepDur=60/cfg.bpm/2;
 while(musicNext<now+.09){
   let s=cfg.pattern[musicStep%cfg.pattern.length];
   tone(hz(cfg.root,s),stepDur*.82,cfg.wave,.045,Math.max(0,musicNext-now),0,'music');
   if(musicStep%4===0)tone(hz(cfg.root/2,0),stepDur*1.7,'sine',.032,Math.max(0,musicNext-now),-.15,'music');
   if(musicStep%8===4)tone(hz(cfg.root,7),stepDur*.65,'triangle',.025,Math.max(0,musicNext-now),.18,'music');
   musicStep++;musicNext+=stepDur;
 }
}
let resetConfirmUntil=0;
function optionValue(i){
 if(i===0)return Math.round(AUDIO.master*100)+'%';
 if(i===1)return Math.round(AUDIO.music*100)+'%';
 if(i===2)return Math.round(AUDIO.sfx*100)+'%';
 if(i===3)return AUDIO.mute?'ON':'OFF';
 if(i===4)return SYSTEM.controls;
 if(i===5)return SYSTEM.deadzone.toFixed(2);
 if(i===6)return SYSTEM.vibration?'ON':'OFF';
 if(i===7)return SYSTEM.shake?'ON':'OFF';
 if(i===8)return SYSTEM.flashes?'ON':'OFF';
 if(i===9)return SYSTEM.reducedMotion?'ON':'OFF';
 if(i===10)return SYSTEM.highContrast?'ON':'OFF';
 if(i===11)return SYSTEM.particles;
 if(i===12)return performance.now()<resetConfirmUntil?'PRESS ENTER AGAIN':'—';
 return '';
}
function adjustAudioOption(dir){
 if(optionsIndex===0)AUDIO.master=clamp(AUDIO.master+dir*.05,0,1);
 else if(optionsIndex===1)AUDIO.music=clamp(AUDIO.music+dir*.05,0,1);
 else if(optionsIndex===2)AUDIO.sfx=clamp(AUDIO.sfx+dir*.05,0,1);
 else if(optionsIndex===3)AUDIO.mute=!AUDIO.mute;
 else if(optionsIndex===4){
   SYSTEM.controls=SYSTEM.controls==='CLASSIC'?'ARCADE':'CLASSIC';
   Object.keys(keys).forEach(k=>keys[k]=0);Object.keys(kbKeys).forEach(k=>kbKeys[k]=0);Object.keys(padKeys).forEach(k=>padKeys[k]=0);
   Object.keys(pressed).forEach(k=>delete pressed[k]);prevPadButtons=[];
 }
 else if(optionsIndex===5)SYSTEM.deadzone=clamp(Math.round((SYSTEM.deadzone+dir*.05)*100)/100,.20,.75);
 else if(optionsIndex===6)SYSTEM.vibration=!SYSTEM.vibration;
 else if(optionsIndex===7)SYSTEM.shake=!SYSTEM.shake;
 else if(optionsIndex===8)SYSTEM.flashes=!SYSTEM.flashes;
 else if(optionsIndex===9)SYSTEM.reducedMotion=!SYSTEM.reducedMotion;
 else if(optionsIndex===10)SYSTEM.highContrast=!SYSTEM.highContrast;
 else if(optionsIndex===11){let p=['NORMAL','LOW','OFF'],idx=p.indexOf(SYSTEM.particles);SYSTEM.particles=p[(idx+(dir>=0?1:p.length-1))%p.length]}
 applyAudioLevels();saveAudio();saveSystem();
 if(optionsIndex===2&&!AUDIO.mute)tone(440,.06,'triangle',.12);
}
function resetProgressSafe(){
 if(performance.now()<resetConfirmUntil){
   try{localStorage.setItem('nightbloom_progress_backup',JSON.stringify(PROGRESS))}catch(e){}
   PROGRESS={version:1,storyClears:{},arcadeBest:{}};saveProgress();resetConfirmUntil=0;
   announcement='PROGRESS RESET · BACKUP SAVED';announceT=55;tone(220,.08,'triangle',.08);return true;
 }
 resetConfirmUntil=performance.now()+4000;announcement='CONFIRM RESET';announceT=45;return false;
}
function hasProgressBackup(){try{return !!localStorage.getItem('nightbloom_progress_backup')}catch(e){return false}}
function restoreProgressBackup(){
 try{
   let raw=localStorage.getItem('nightbloom_progress_backup');if(!raw)return false;
   let p=JSON.parse(raw);PROGRESS={version:1,storyClears:p.storyClears||{},arcadeBest:p.arcadeBest||{}};
   repairProgress();saveProgress();announcement='PROGRESS BACKUP RESTORED';announceT=55;return true;
 }catch(e){return false}
}
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)), rnd=(a,b)=>a+Math.random()*(b-a);
