const floorStones=Array.from({length:24},(_,i)=>({x:i*44+(i%2)*10,y:ground+5+stageRng()*85,w:20+stageRng()*18}));
const reflections=Array.from({length:10},()=>({x:stageRng()*W,y:ground+5+stageRng()*85,w:40+stageRng()*110}));
