const MATCH_RULE_OPTIONS=['ROUNDS TO WIN','ROUND TIMER','STARTING METER','CPU DIFFICULTY','REMATCH STAGE','START MATCH'];
const MATCH_RULE_DEFAULT={roundsToWin:2,timer:99,startMeter:0,cpuDifficulty:'NORMAL',rematchStage:'KEEP'};
let MATCH_RULES={...MATCH_RULE_DEFAULT};
try{let m=JSON.parse(localStorage.getItem('nightbloom_match_rules')||'null');if(m)MATCH_RULES={...MATCH_RULES,...m}}catch(e){}
function repairMatchRules(){
 MATCH_RULES.roundsToWin=[1,2,3].includes(Number(MATCH_RULES.roundsToWin))?Number(MATCH_RULES.roundsToWin):2;
 MATCH_RULES.timer=[60,90,99,0].includes(Number(MATCH_RULES.timer))?Number(MATCH_RULES.timer):99;
 MATCH_RULES.startMeter=[0,50,100].includes(Number(MATCH_RULES.startMeter))?Number(MATCH_RULES.startMeter):0;
 if(!['EASY','NORMAL','HARD','NIGHTMARE'].includes(MATCH_RULES.cpuDifficulty))MATCH_RULES.cpuDifficulty='NORMAL';
 if(!['KEEP','RANDOM'].includes(MATCH_RULES.rematchStage))MATCH_RULES.rematchStage='KEEP';
}
function saveMatchRules(){repairMatchRules();try{localStorage.setItem('nightbloom_match_rules',JSON.stringify(MATCH_RULES))}catch(e){}}
repairMatchRules();
function versusRulesActive(){return gameMode==='versus'||gameMode==='local'}
function winsNeeded(){return versusRulesActive()?MATCH_RULES.roundsToWin:2}
function timerInfinite(){return versusRulesActive()&&MATCH_RULES.timer===0}
function configuredTimer(){return versusRulesActive()?MATCH_RULES.timer:99}
function isFinalRound(){let n=winsNeeded();return p1Wins===n-1&&p2Wins===n-1}
function matchFormatLabel(){let n=winsNeeded();return 'FT'+n+' · '+(timerInfinite()?'∞':MATCH_RULES.timer)+' SEC'}

