const ENDINGS={
 VAMPIRA:'Vampira stands beneath a sunrise she was never meant to see. The Red Moon has withdrawn, but its taste remains in every shadow. She smiles—not because the night survived, but because hunger did.',
 NEKOMATA:'Nekomata watches dawn split into two reflections across the shrine pond. One tail curls toward home. The other points toward whatever impossible thing comes next.',
 BANSHEE:'Banshee sings one final note into the morning. This time, the world answers instead of echoing. For the first time in centuries, her song belongs to the living as much as the dead.',
 MEDUSA:'Medusa walks through a garden of statues warmed by sunrise. Hair-serpents blink at the light. Nothing turns away. She decides eternity may be tolerable if it can still surprise her.',
 JIANGSHI:'Jiangshi reaches the edge of dawn and stops. Her talisman flutters once, then lies still. The seal remains intact—but now it feels less like a prison and more like a choice.',
 YUREI:'Yūrei fades with the last violet edge of night, then reappears in the reflection of morning glass. Dawn cannot exorcise a memory that has learned its own name.',
 DULLAHAN:'Dullahan rides directly into sunrise with her head tucked under one arm. The road does not end. It merely becomes visible.',
 WEREWOLF:'Werewolf watches the moon vanish and discovers the hunt does not. Daylight only gives the world fewer places to hide.',
 MUMMY:'Mummy enters dawn carrying nine new curses and one old name. Sunlight warms the wrappings. Nothing turns to dust. Somewhere beneath the linen, she laughs.',
 WITCH:'Witch closes her grimoire as sunrise turns every sigil pale gold. The universe remains stubbornly intact, which means there is still plenty left to rewrite.'
};
const PRE_FIGHT_LINES={
 VAMPIRA:'Come closer, {opponent}. I prefer my nightmares warm.',
 NEKOMATA:'Try to keep up, {opponent}. I have lives to spare.',
 BANSHEE:'Listen carefully, {opponent}. The next sound is for you.',
 MEDUSA:'Look at me when I end this, {opponent}.',
 JIANGSHI:'Seal intact. Target: {opponent}. Proceeding.',
 YUREI:'You have been standing beside a ghost longer than you think, {opponent}.',
 DULLAHAN:'Choose a road, {opponent}. I will meet you at the end of it.',
 WEREWOLF:'Run if you want, {opponent}. It improves the hunt.',
 MUMMY:'Stand still, {opponent}. The wrappings work better that way.',
 WITCH:'Careful, {opponent}. You are standing inside the spell already.'
};
let PROGRESS={version:1,storyClears:{},arcadeBest:{}};
try{
 let p=JSON.parse(localStorage.getItem('nightbloom_progress')||'null');
 if(p)PROGRESS={version:1,storyClears:p.storyClears||{},arcadeBest:p.arcadeBest||{}}
}catch(e){}
function repairProgress(){
 let known=new Set(ROSTER);
 for(let k of Object.keys(PROGRESS.storyClears||{}))if(!known.has(k))delete PROGRESS.storyClears[k];
 for(let k of Object.keys(PROGRESS.arcadeBest||{})){
   let fighter=k.split('_')[0],v=Number(PROGRESS.arcadeBest[k]);
   if(!known.has(fighter)||!Number.isFinite(v)||v<0)delete PROGRESS.arcadeBest[k];
   else PROGRESS.arcadeBest[k]=Math.floor(v);
 }
 PROGRESS.version=1;
}
function saveProgress(){repairProgress();try{localStorage.setItem('nightbloom_progress',JSON.stringify(PROGRESS))}catch(e){}}
repairProgress();
function unlockStoryClear(name){PROGRESS.storyClears[name]=true;saveProgress()}
function saveArcadeBest(name,score){
 let key=name+'_'+difficulty,old=PROGRESS.arcadeBest[key]||0;
 if(score>old){PROGRESS.arcadeBest[key]=score;saveProgress()}
}
function rivalLine(name,other){return (PRE_FIGHT_LINES[name]||'Face me, {opponent}.').replace('{opponent}',other)}
function routeRank(score){
 if(score>=85000)return 'S';
 if(score>=68000)return 'A';
 if(score>=52000)return 'B';
 if(score>=36000)return 'C';
 return 'D';
}
function calcMatchBonuses(){
 let health=Math.round((p1.hp/p1.maxhp)*5000);
 let time=Math.max(0,Math.round(timer))*45;
 let combo=matchPeakCombo*320;
 let clear=1800;
 let raw=health+time+combo+clear;
 let mult=DIFFICULTIES[difficulty]?.score||1;
 return {health,time,combo,clear,mult,total:Math.round(raw*mult)};
}
function wrapLines(text,maxWidth,font){
 x.font=font;let words=String(text||'').split(' '),lines=[],line='';
 for(let w of words){
   let test=line?line+' '+w:w;
   if(x.measureText(test).width>maxWidth&&line){lines.push(line);line=w}else line=test;
 }
 if(line)lines.push(line);return lines;
}
