function buildLadder(mode,name){
 let order=(STORY_ROUTES[name]||[]).map(n=>({...n}));
 if(mode==='arcade'){
   return order.map((n,i)=>({...n,title:'Arcade Match '+(i+1),before:'',after:''}));
 }
 return order;
}
function beginRoute(mode){
 gameMode=mode;ladder=buildLadder(mode,playerChoice);ladderIndex=0;storyEnding=false;storyLost=false;storyAfterText='';routeHandled=false;
 continueCredits=DIFFICULTIES[difficulty]?.continues||3;routeScore=0;lastMatchScore=0;lastBonuses=null;
 if(mode==='story'){gameState='storyScene'}
 else startRouteFight();
}
function startRouteFight(){
 let node=ladder[ladderIndex];
 if(!node){gameState='routeComplete';return}
 enemyChoice=node.opponent;selectedStage=node.stage;routeHandled=false;startFight();gameMode=gameMode;
}
function advanceRoute(){
 if(!matchOver||routeHandled)return;
 routeHandled=true;
 let playerWon=p1Wins>p2Wins;
 if(!playerWon){gameState='continueScreen';sweep(180,62,.35,'sawtooth',.13);return}
 let node=ladder[ladderIndex];
 if(gameMode==='arcade'){
   lastBonuses=calcMatchBonuses();lastMatchScore=lastBonuses.total;routeScore+=lastMatchScore;
   tone(440,.07,'triangle',.09);tone(660,.09,'triangle',.08,.06);
 }
 if(gameMode==='story')storyAfterText=node?.after||'';
 ladderIndex++;
 if(gameMode==='story'){
   if(ladderIndex>=ladder.length){storyEnding=true;unlockStoryClear(playerChoice)}
   gameState='storyScene';
 }else{
   if(ladderIndex>=ladder.length){saveArcadeBest(playerChoice,routeScore);gameState='routeComplete'}
   else gameState='arcadeResult';
 }
}

