function drawInspectorFrameLayers(body,fx,meta,fighter,action,index,col,sx,sy,px,py,pw,ph){
 if(fighter==='DULLAHAN'){
   const unit=Math.min(pw/320,ph/256);x.save();x.beginPath();x.rect(px,py,pw,ph);x.clip();
   x.translate(px+(pw-320*unit)/2+160*unit,py+(ph-256*unit)/2+216*unit);x.scale(unit,unit);
   if(inspectorLayerMode!==1){drawDullahanPropPart(x,action,index,true,'lance');drawIsolatedAtlasCell(x,body,sx,sy,192,192,-96,-184,192,192);drawDullahanPropPart(x,action,index,action!=='specialB'||index===0,'head');}
   if(inspectorLayerMode!==0&&fx&&fx.complete&&fx.naturalWidth){const ofs=actionFxOffset(fighter,action,index),row=(REMADE_ANIMS[action]||REMADE_ANIMS.idle).row;drawIsolatedAtlasCell(x,fx,col*128,row*160,128,160,-64+ofs.x,-154+ofs.y,128,160);}
   x.restore();return;
 }

 const scale=Math.min(pw/meta.cellW,ph/meta.cellH);
 const dw=meta.cellW*scale,dh=meta.cellH*scale;
 const dx=px+(pw-dw)/2,dy=py+(ph-dh)/2;
 x.save();x.beginPath();x.rect(px,py,pw,ph);x.clip();
 if(inspectorLayerMode!==1)drawIsolatedAtlasCell(x,body,sx,sy,meta.cellW,meta.cellH,dx,dy,dw,dh);
 if(inspectorLayerMode!==0&&meta.remade&&fx&&fx.complete&&fx.naturalWidth){
   const ofs=actionFxOffset(fighter,action,index);
   const row=(REMADE_ANIMS[action]||REMADE_ANIMS.idle).row;
   const baseline=dy+(bodyCellFor(fighter).baseline||154)*scale;
   drawIsolatedAtlasCell(x,fx,col*128,row*160,128,160,
     dx+dw/2+(-64+ofs.x)*scale,baseline+(-154+ofs.y)*scale,128*scale,160*scale);
 }
 x.restore();
}
function drawFighterFxLayer(name,action,frame,worldX,worldY,w,h,flip){
 if(name==='DULLAHAN'&&action==='specialB')return; // The projectile carries the single head.
 let info=REMADE_ANIMS[action]||REMADE_ANIMS.idle;
 let frames=info.frames||[0,1,2,3];
 let col=frames[frame%frames.length], row=info.row;
 let img=fxSpriteFor(name);
 if(!img||!img.complete||!img.naturalWidth)return;
 let ofs=actionFxOffset(name,action,frame);
 x.save();
 x.imageSmoothingEnabled=false;
 x.translate(Math.round(worldX),Math.round(worldY));
 if(flip)x.scale(-1,1);
 x.globalAlpha=.95;
 drawIsolatedAtlasCell(x,img,col*REMADE_CELL.w,row*REMADE_CELL.h,REMADE_CELL.w,REMADE_CELL.h,
             -Math.round(w/2)+ofs.x,-154-Math.round((h-160))+ofs.y,w,h);
 x.globalAlpha=1;
 x.restore();
}

