let balanceOverlay=false;
let MATCH_STATS=null;
const SESSION_BALANCE={matches:0,fighters:{}};
function emptyFighterStats(name){
 return {name,attacks:0,hits:0,blocks:0,damage:0,chip:0,damageTaken:0,throws:0,supers:0,counters:0,techs:0,peakCombo:0};
}
function resetMatchStats(){
 MATCH_STATS={start:performance.now(),p1:emptyFighterStats(playerChoice),p2:emptyFighterStats(enemyChoice),rounds:0};
}
function statFor(name){
 if(!MATCH_STATS)return null;
 return MATCH_STATS.p1.name===name?MATCH_STATS.p1:MATCH_STATS.p2.name===name?MATCH_STATS.p2:null;
}
function balanceEvent(type,data={}){
 if(!MATCH_STATS)return;
 if(type==='attack'){
   let s=statFor(data.fighter);if(s){s.attacks++;if(data.move==='throw')s.throws++;if(data.move==='super')s.supers++}
 }else if(type==='hit'||type==='block'){
   let a=statFor(data.attacker),d=statFor(data.defender),dmg=Number(data.damage)||0;
   if(training&&data.attacker===p1?.name){trainingLastDamage=dmg;trainingLastEvent=(type==='block'?'BLOCK ':'HIT ')+(data.move||'');}
   if(a){if(type==='hit')a.hits++;else{a.blocks++;a.chip+=dmg}a.damage+=dmg;if(data.counter)a.counters++}
   if(d)d.damageTaken+=dmg;
 }else if(type==='throw_tech'||type==='ground_tech'||type==='air_tech'){
   let s=statFor(data.fighter||data.defender);if(s)s.techs++;
 }else if(type==='round_start'){
   MATCH_STATS.rounds=Math.max(MATCH_STATS.rounds,Number(data.round)||1);
 }else if(type==='match_end'){
   MATCH_STATS.duration=(performance.now()-MATCH_STATS.start)/1000;
   if(p1){MATCH_STATS.p1.peakCombo=p1.peakCombo||0;MATCH_STATS.p2.peakCombo=p2.peakCombo||0}
   MATCH_STATS.winner=data.winner;commitMatchStats();
 }
}
function commitMatchStats(){
 if(!MATCH_STATS||MATCH_STATS.committed)return;
 MATCH_STATS.committed=true;SESSION_BALANCE.matches++;
 for(let s of [MATCH_STATS.p1,MATCH_STATS.p2]){
   let a=SESSION_BALANCE.fighters[s.name]||(SESSION_BALANCE.fighters[s.name]={matches:0,wins:0,damage:0,damageTaken:0,hits:0,attacks:0,peakCombo:0});
   a.matches++;if(MATCH_STATS.winner===s.name)a.wins++;a.damage+=s.damage;a.damageTaken+=s.damageTaken;a.hits+=s.hits;a.attacks+=s.attacks;a.peakCombo=Math.max(a.peakCombo,s.peakCombo);
 }
}
function hitRate(s){return s&&s.attacks?Math.round(s.hits/s.attacks*100):0}
function sessionWinRate(name){let s=SESSION_BALANCE.fighters[name];return s&&s.matches?Math.round(s.wins/s.matches*100):0}
function balanceFlags(s){
 let f=[];if(!s)return f;
 if(s.attacks>=10&&hitRate(s)>=68)f.push('HIGH CONNECT');
 if(s.damage>=650)f.push('HIGH DAMAGE');
 if(s.blocks>=8&&s.chip>=80)f.push('CHIP PRESSURE');
 if(s.supers>=3)f.push('SUPER FREQUENCY');
 return f;
}
function matchupBias(f,o){
 let ap=AI_PROFILES[f.name]||AI_PROFILES.VAMPIRA,b={guard:1,jump:1,dash:1,projectile:1,retreat:1};
 if(['WITCH','MUMMY','BANSHEE','MEDUSA'].includes(o.name)){b.dash=1.22;b.jump=1.15;b.guard=1.08}
 if(['WEREWOLF','VAMPIRA','NEKOMATA'].includes(o.name)){b.guard=1.18;b.retreat=1.22;b.projectile=1.10}
 if(o.name==='DULLAHAN'&&o.headless>0){b.dash=1.12;b.guard=.92}
 if(o.name==='WITCH'&&witchSigils.some(s=>s.owner===o&&Math.abs(s.x-f.x)<105)){b.jump=1.55;b.retreat=1.35}
 if(o.curseStacks>=2){b.guard=1.18;b.dash=1.12}
 return b;
}
