function rectHit(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y}
function hurtbox(f){return{x:f.x-f.w/2,y:f.y-f.h,w:f.w,h:f.h}}
function face(){p1.flip=p1.x>p2.x;p2.flip=p2.x>p1.x}
function toward(f){return f.flip?-1:1}
function awayHeld(f){
 return f.flip ? heldFor(f,'KeyD') : heldFor(f,'KeyA');
}
function resolvePushboxes(a,b){
 if(a.air||b.air)return;
 let min=52,d=b.x-a.x,ad=Math.abs(d);
 if(ad<min&&ad>0){let push=(min-ad)/2,sg=Math.sign(d);
   let aEdge=a.x<=47||a.x>=W-47,bEdge=b.x<=47||b.x>=W-47;
   if(aEdge&&!bEdge)b.x+=push*2*sg;else if(bEdge&&!aEdge)a.x-=push*2*sg;else{a.x-=push*sg;b.x+=push*sg}
   a.x=clamp(a.x,45,W-45);b.x=clamp(b.x,45,W-45)
 }
 a.cornered=a.x<=48||a.x>=W-48;b.cornered=b.x<=48||b.x>=W-48;
}
function bufferInput(f,code){f.inputBuffer.push({code,t:10})}
function consumeBuffer(f,code){let i=f.inputBuffer.findIndex(v=>v.code===code&&v.t>0);if(i>=0){f.inputBuffer.splice(i,1);return true}return false}
function dirCode(f){
 let L=heldFor(f,'KeyA'),R=heldFor(f,'KeyD'),D=heldFor(f,'KeyS');
 if(D&&R)return f.flip?'DB':'DF';if(D&&L)return f.flip?'DF':'DB';
 if(D)return 'D';if(R)return f.flip?'B':'F';if(L)return f.flip?'F':'B';return 'N';
}
function recordMotion(f){
 if(f.ai)return;let d=dirCode(f);
 if(d!==f.lastDir){f.motionHistory.push({d,t:18});if(f.motionHistory.length>18)f.motionHistory.shift();f.lastDir=d}
}
function ageMotions(dt){
 for(let f of [p1,p2])if(f){f.motionHistory.forEach(m=>m.t-=dt);f.motionHistory=f.motionHistory.filter(m=>m.t>0)}
}
function motion(f,seq){
 let h=f.motionHistory,j=h.length-1;
 for(let i=seq.length-1;i>=0;i--){while(j>=0&&h[j].d!==seq[i])j--;if(j<0)return false;j--}
 return true;
}
function motionAny(f,seqs){return seqs.some(s=>motion(f,s))}
function clearMotion(f){f.motionHistory=[]}
function updateBuffer(dt){
 for(let f of [p1,p2])if(f){f.inputBuffer.forEach(v=>v.t-=dt);f.inputBuffer=f.inputBuffer.filter(v=>v.t>0)}
}
