function canCancelAttack(f,to){
 let a=f.attack;if(!a)return false;
 let routes=CANCEL_ROUTES[a.type]||[];
 if(!routes.includes(to))return false;
 if((a.type==='specialA'||a.type==='specialB')&&to==='super'&&!a.hit)return false;
 let activeEnd=a.start+a.active;
 return a.hit ? a.frame>=a.start : a.frame>=activeEnd;
}
