 def.hitstun=def.blockstun=0;att.hitstun=att.blockstun=0;
 def.vx=dir*3.6;att.vx=-dir*3.6;
 def.invuln=Math.max(def.invuln,5);att.invuln=Math.max(att.invuln,5);
 spawnHit((def.x+att.x)/2,def.y-60,'#ffffff',12);
