 x.save();x.lineWidth=2;
 [p1,p2].forEach(f=>{let h=hurtbox(f);x.strokeStyle='#4bff70';x.strokeRect(h.x,h.y,h.w,h.h);
 if(f.attack){let a=f.attack,dir=f.flip?-1:1;if(a.frame>=a.start&&a.frame<a.start+a.active){let hb={x:f.x+(dir>0?22:-22-a.reach),y:f.y-f.h+18,w:a.reach,h:f.h-28};x.strokeStyle='#ff3d55';x.strokeRect(hb.x,hb.y,hb.w,hb.h)}}});
 x.fillStyle='#fff';x.font='11px Consolas';x.textAlign='left';x.fillText('DEBUG HITBOXES [F2]',12,105);
