const FINAL_STAGE_BACKDROP_URIS={
 'CRIMSON CATHEDRAL':'data:image/webp;base64,',
 'MOONLIT SHRINE':'data:image/webp;base64,',
 'FORSAKEN HARBOR':'data:image/webp;base64,',
 'CURSED LIBRARY':'data:image/webp;base64,',
 'BONEFIELD':'data:image/webp;base64,',
 'THE NEXT DAWN':'data:image/webp;base64,'
};
const FINAL_STAGE_BACKDROPS={};
Object.keys(FINAL_STAGE_BACKDROP_URIS).forEach(k=>{let im=new Image();im.src=FINAL_STAGE_BACKDROP_URIS[k];FINAL_STAGE_BACKDROPS[k]=im;});
function drawStageBackdrop(stageName){
 let img=FINAL_STAGE_BACKDROPS[stageName];
 if(!(img&&img.complete&&img.naturalWidth))return false;
 x.save();
 x.drawImage(img,0,0,W,H);
 let g=x.createLinearGradient(0,0,0,H);
 g.addColorStop(0,'rgba(0,0,0,0)');
 g.addColorStop(.58,'rgba(0,0,0,.04)');
 g.addColorStop(1,'rgba(0,0,0,.22)');
 x.fillStyle=g;x.fillRect(0,0,W,H);
 x.fillStyle='rgba(0,0,0,.12)';x.fillRect(0,ground+3,W,H-ground);
 x.strokeStyle='rgba(255,255,255,.08)';x.lineWidth=1;x.beginPath();x.moveTo(0,ground+.5);x.lineTo(W,ground+.5);x.stroke();
 x.restore();
 return true;
}
