function rgba(hex,a){
 let h=hex.replace('#','');if(h.length===3)h=h.split('').map(v=>v+v).join('');
 let n=parseInt(h,16);return 'rgba('+((n>>16)&255)+','+((n>>8)&255)+','+(n&255)+','+a+')';
}
function roundRect(px,py,w,h,r,fill,stroke=null,lineW=1){
 x.beginPath();x.moveTo(px+r,py);x.arcTo(px+w,py,px+w,py+h,r);x.arcTo(px+w,py+h,px,py+h,r);x.arcTo(px,py+h,px,py,r);x.arcTo(px,py,px+w,py,r);x.closePath();
 if(fill){x.fillStyle=fill;x.fill()}if(stroke){x.strokeStyle=stroke;x.lineWidth=lineW;x.stroke()}
}
function glowText(text,px,py,size,fill,glow='#000',align='center',font='Georgia'){
 x.save();x.textAlign=align;x.font='bold '+size+'px '+font;x.shadowColor=glow;x.shadowBlur=18;x.fillStyle=fill;x.fillText(text,px,py);x.shadowBlur=0;x.restore();
}
