function addDiagnostic(name,status,detail){
 diagnosticResults.push({name,status,detail:String(detail||'')});
}
function runReleaseDiagnostics(){
 diagnosticResults=[];diagnosticCopied=false;
 let routeOK=true,routeDetail=[];
 for(let name of ROSTER){
   let r=STORY_ROUTES[name]||[],opps=r.map(v=>v.opponent),unique=new Set(opps);
   let ok=r.length===ROSTER.length-1&&unique.size===ROSTER.length-1&&!unique.has(name)&&ROSTER.filter(n=>n!==name).every(n=>unique.has(n));
   if(!ok)routeOK=false;
   if(!ok)routeDetail.push(name+':'+r.length+'/'+unique.size);
 }
 addDiagnostic('Core roster',ROSTER.length===10?'PASS':'FAIL',ROSTER.length+' fighters');
 addDiagnostic('Stage roster',STAGES.length===6?'PASS':'FAIL',STAGES.length+' stages');
 addDiagnostic('Story route integrity',routeOK?'PASS':'FAIL',routeOK?'10 × 9 complete':routeDetail.join(', '));
 let cfgOK=ROSTER.every(n=>CHAR_INFO[n]&&MOVESETS[n]&&MOVE_NAMES[n]&&AI_PROFILES[n]);
 addDiagnostic('Fighter config coverage',cfgOK?'PASS':'FAIL',cfgOK?'metadata / moves / AI complete':'missing fighter config');
 let artReady=ROSTER.every(n=>{let a=portraitFor(n),b=spriteFor(n);return a&&b&&a.complete&&b.complete&&a.naturalWidth>0&&b.naturalWidth>0});
 addDiagnostic('Embedded fighter art',artReady?'PASS':'WARN',artReady?'all portrait/sprite atlases ready':'one or more images still loading');
 let fxReady=fxAtlas&&fxAtlas.complete&&fxAtlas.naturalWidth>0&&fxAtlas.naturalHeight>=FX.cell*22;
 addDiagnostic('FX atlas',fxReady?'PASS':'WARN',fxReady?'22 effect rows ready':'FX image pending or incomplete');
 let progKeys=Object.keys(PROGRESS.storyClears||{}).every(k=>ROSTER.includes(k));
 let scoreKeys=Object.keys(PROGRESS.arcadeBest||{}).every(k=>ROSTER.some(n=>k.startsWith(n+'_'))&&Number.isFinite(Number(PROGRESS.arcadeBest[k])));
 addDiagnostic('Save schema',progKeys&&scoreKeys?'PASS':'FAIL','progress v'+(PROGRESS.version||1));
 let mr=[1,2,3].includes(MATCH_RULES.roundsToWin)&&[60,90,99,0].includes(MATCH_RULES.timer)&&[0,50,100].includes(MATCH_RULES.startMeter)&&['EASY','NORMAL','HARD','NIGHTMARE'].includes(MATCH_RULES.cpuDifficulty)&&['KEEP','RANDOM'].includes(MATCH_RULES.rematchStage);
 addDiagnostic('Versus rule schema',mr?'PASS':'FAIL',matchFormatLabel()+' / '+MATCH_RULES.cpuDifficulty);
 let sys=['CLASSIC','ARCADE'].includes(SYSTEM.controls)&&SYSTEM.deadzone>=.20&&SYSTEM.deadzone<=.75&&['NORMAL','LOW','OFF'].includes(SYSTEM.particles);
 addDiagnostic('Options schema',sys?'PASS':'FAIL',SYSTEM.controls+' / deadzone '+SYSTEM.deadzone.toFixed(2));
 let storageOK=false;
 try{localStorage.setItem('nightbloom_rc_test','1');storageOK=localStorage.getItem('nightbloom_rc_test')==='1';localStorage.removeItem('nightbloom_rc_test')}catch(e){}
 addDiagnostic('Local save access',storageOK?'PASS':'WARN',storageOK?'read/write available':'browser storage blocked');
 let backup=hasProgressBackup();
 addDiagnostic('Progress reset backup',backup?'PASS':'INFO',backup?'backup available · B restores it':'no reset backup yet');
 let audioOK=!!(window.AudioContext||window.webkitAudioContext);
 addDiagnostic('WebAudio capability',audioOK?'PASS':'WARN',audioOK?(audioUnlocked?'available / active':'available / unlock on input'):'unsupported browser');
 let gpOK=!!navigator.getGamepads;
 addDiagnostic('Gamepad API',gpOK?'PASS':'WARN',gpOK?(gamepadConnected?(gamepad2Connected?'2 pads detected':'1 pad detected'):'supported / none connected'):'unsupported browser');
 let inputOK=Object.keys(P2_KEYMAP).length===10&&typeof heldFor==='function'&&typeof pressedFor==='function';
 addDiagnostic('Local input isolation',inputOK?'PASS':'FAIL',inputOK?'P1/P2 buffers isolated':'input mapping incomplete');
 let capsOK=particles.length<=PERF_CAPS.particles&&fxInstances.length<=PERF_CAPS.fx&&projectiles.length<=PERF_CAPS.projectiles&&witchSigils.length<=PERF_CAPS.sigils;
 addDiagnostic('Runtime effect caps',capsOK?'PASS':'FAIL','P '+particles.length+'/'+PERF_CAPS.particles+' · FX '+fxInstances.length+'/'+PERF_CAPS.fx+' · Q '+projectiles.length+'/'+PERF_CAPS.projectiles+' · S '+witchSigils.length+'/'+PERF_CAPS.sigils);
 let stateOK=['title','options','gallery','difficultySelect','arcadeResult','continueScreen','matchSetup','matchResult','charSelect','stageSelect','storyScene','routeComplete','fight','diagnostics','credits'].includes(gameState);
 addDiagnostic('Frontend state',stateOK?'PASS':'FAIL',gameState);
 let perfStatus=perfLowFrames>120?'WARN':'PASS';
 addDiagnostic('Performance monitor',perfStatus,'~'+perfFPS.toFixed(0)+' FPS · low-frame count '+perfLowFrames);
 diagnosticRunAt=performance.now();
 return diagnosticResults;
}
function diagnosticSummary(){
 let fail=diagnosticResults.filter(r=>r.status==='FAIL').length,warn=diagnosticResults.filter(r=>r.status==='WARN').length,pass=diagnosticResults.filter(r=>r.status==='PASS').length;
 return {fail,warn,pass};
}
function diagnosticText(){
 let h='NIGHTBLOOM '+BUILD_INFO.version+' '+BUILD_INFO.channel+' SYSTEM CHECK\n';
 return h+diagnosticResults.map(r=>'['+r.status+'] '+r.name+' — '+r.detail).join('\n');
}
function copyDiagnostics(){
 let text=diagnosticText();
 if(navigator.clipboard?.writeText){
   navigator.clipboard.writeText(text).then(()=>{diagnosticCopied=true}).catch(()=>{diagnosticCopied=false});
 }
}
