function matchRuleValue(i){
 if(i===0)return 'FIRST TO '+MATCH_RULES.roundsToWin;
 if(i===1)return MATCH_RULES.timer===0?'INFINITE':MATCH_RULES.timer+' SECONDS';
 if(i===2)return MATCH_RULES.startMeter+'%';
 if(i===3)return gameMode==='local'?'—':MATCH_RULES.cpuDifficulty;
 if(i===4)return MATCH_RULES.rematchStage;
 return 'FIGHT';
}
function adjustMatchRule(dir){
 if(matchSetupIndex===0){let a=[1,2,3],i=a.indexOf(MATCH_RULES.roundsToWin);MATCH_RULES.roundsToWin=a[(i+(dir>0?1:a.length-1))%a.length]}
 else if(matchSetupIndex===1){let a=[60,90,99,0],i=a.indexOf(MATCH_RULES.timer);MATCH_RULES.timer=a[(i+(dir>0?1:a.length-1))%a.length]}
 else if(matchSetupIndex===2){let a=[0,50,100],i=a.indexOf(MATCH_RULES.startMeter);MATCH_RULES.startMeter=a[(i+(dir>0?1:a.length-1))%a.length]}
 else if(matchSetupIndex===3&&gameMode!=='local'){let a=DIFFICULTY_ORDER,i=a.indexOf(MATCH_RULES.cpuDifficulty);MATCH_RULES.cpuDifficulty=a[(i+(dir>0?1:a.length-1))%a.length]}
 else if(matchSetupIndex===4)MATCH_RULES.rematchStage=MATCH_RULES.rematchStage==='KEEP'?'RANDOM':'KEEP';
 saveMatchRules();
}
